 * Per-key state for the two policy kinds. Each policy declaration owns one
 * `Map` from key to that key's independent state.
 */

/**
 * A token bucket. Tokens are tracked scaled by `per` so that refilling by a
 * partial period never loses precision: `tokensScaled` holds `per` times the
 * true token count, and both `refill` and `per` are integers, so every
 * update stays exact.
 */
export class BucketPolicy {
  constructor({ capacity, refill, per }) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.fullScaled = capacity * per
    this.states = new Map()
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { tokensScaled: this.fullScaled, lastTick: tick }
      this.states.set(key, state)
      return
    }
    const elapsed = tick - state.lastTick
    if (elapsed > 0n) {
      let tokensScaled = state.tokensScaled + this.refill * elapsed
      if (tokensScaled > this.fullScaled) tokensScaled = this.fullScaled
      state.tokensScaled = tokensScaled
      state.lastTick = tick
    }
  }

  allows(key) {
    return this.states.get(key).tokensScaled >= this.per
  }

  record(key) {
    this.states.get(key).tokensScaled -= this.per
  }
}

/**
 * A sliding window. Recorded ticks are kept in arrival order, which is also
 * tick order since ticks never go backwards across the file, so expiring the
 * oldest entries is a simple prefix trim.
 */
export class WindowPolicy {
  constructor({ limit, span }) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  advance(key, tick) {
    let ticks = this.states.get(key)
    if (ticks === undefined) {
      ticks = []
      this.states.set(key, ticks)
    }
    const threshold = tick - this.span
    let cut = 0
    while (cut < ticks.length && ticks[cut] <= threshold) cut++
    if (cut > 0) ticks.splice(0, cut)
  }

  allows(key) {
    return this.states.get(key).length < this.limit
  }

  record(key) {
    this.states.get(key).push(this.states.get(key).slice(-1)[0])
  }
}
"}

