  const perKey = new Map()
  let totalAllowed = 0
  let totalDenied = 0
  for (const r of results) {
    let stats = perKey.get(r.key)
    if (stats === undefined) {
      stats = { allowed: 0, denied: 0 }
      perKey.set(r.key, stats)
    }
    if (r.allow) {
      stats.allowed++
      totalAllowed++
    } else {
      stats.denied++
      totalDenied++
    }
  }
  const keys = [...perKey.keys()].sort()
  const lines = keys.map((key) => {
    const stats = perKey.get(key)
    return `${key} allowed=${stats.allowed} denied=${stats.denied}`
  })
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  return lines
}

